import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"ADR index","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/adrs/README.md"},"headers":[],"relativePath":"apps/mobile/adrs/README.md","filePath":"apps/mobile/adrs/README.md"}'),d={name:"apps/mobile/adrs/README.md"};function s(i,e,n,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-index" tabindex="-1">ADR index <a class="header-anchor" href="#adr-index" aria-label="Permalink to &quot;ADR index&quot;">​</a></h1><p>Architecture Decision Records for <code>sovereign-mobile</code> — accepted decisions with binding consequences, kept even after implementation lands. Contrast with <a href="./../research/README.html">docs/research/</a>: research captures an open question before a decision exists; an ADR records the decision itself.</p><p>This repo adopts the ADR status vocabulary from <code>sovereign-os</code> (the only other repo in the ecosystem using ADRs), since <code>sovereign</code> itself has no ADR stage — see <a href="./../../../confluence/concepts/cross-repo-conventions.html">cross-repo-conventions</a> for why documentation systems differ per repo and don&#39;t transfer.</p><h2 id="status-vocabulary" tabindex="-1">Status vocabulary <a class="header-anchor" href="#status-vocabulary" aria-label="Permalink to &quot;Status vocabulary&quot;">​</a></h2><p><code>Draft</code> → <code>Proposed</code> → <code>Accepted</code> → <code>Implemented</code>, or <code>Superseded</code> / <code>Rejected</code> / <code>Archived</code> at any point after <code>Proposed</code>.</p><p>Most ADRs in this repo start life as <code>Accepted</code>, not <code>Draft</code> — they record decisions already locked centrally in <a href="https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0058-native-mobile-app-shell.md" target="_blank" rel="noreferrer">sovereign RFC 0058</a> and <a href="https://github.com/sovereignfs/sovereign/blob/main/docs/workstreams/0002-native-mobile-app-release.md" target="_blank" rel="noreferrer">workstream 0002</a>&#39;s &quot;Decisions locked&quot; table before this repository existed. Citing &quot;sovereign RFC 0058&quot; rather than a bare &quot;RFC 0058&quot; is deliberate — <code>sovereign-os</code> runs an unrelated RFC numbering series, and the convention in this ecosystem is to always name which repo a citation belongs to.</p><h2 id="index" tabindex="-1">Index <a class="header-anchor" href="#index" aria-label="Permalink to &quot;Index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ADR</th><th>Title</th><th>Status</th></tr></thead><tbody><tr><td><a href="./0001-capacitor-as-shell-technology.html">0001</a></td><td>Capacitor as the shell technology</td><td>Accepted</td></tr><tr><td><a href="./0002-universal-one-binary-distribution.html">0002</a></td><td>One universal binary, not a build per instance</td><td>Accepted</td></tr><tr><td><a href="./0003-cookie-in-webview-auth.html">0003</a></td><td>Cookie-in-WebView auth, not OAuth, for v1</td><td>Accepted</td></tr><tr><td><a href="./0004-shared-device-bridge-contract-with-desktop.html">0004</a></td><td>Device bridge is a shared, versioned contract with <code>sovereign-desktop</code></td><td>Accepted</td></tr><tr><td><a href="./0005-server-url-not-bundled-assets.html">0005</a></td><td>WebView loads <code>server.url</code>, never bundled <code>capacitor://</code> assets</td><td>Accepted</td></tr><tr><td><a href="./0006-history-based-instance-switch-affordance.html">0006</a></td><td>History-based instance-switch affordance, not native menu</td><td>Accepted</td></tr><tr><td><a href="./0007-navigation-policy-enforcement.html">0007</a></td><td>Navigation policy enforced by a thin native WebView delegate</td><td>Accepted</td></tr></tbody></table><p>ADRs 0001–0005 restate decisions already locked centrally before this repo had code. ADRs 0006–0007 are this repo&#39;s own — decided directly during task 20.1&#39;s implementation, since neither has a <code>sovereign-desktop</code> precedent that transfers as-is.</p><p>Add a row here whenever a new ADR file is added.</p>',10)])])}const u=t(d,[["render",s]]);export{b as __pageData,u as default};
